theme.css:
#wemd{color:#1a1a1a;background-color:#fafaf7;font-family:'Helvetica Neue', 'Inter', -apple-system, 'Noto Sans SC', sans-serif;font-size:16px;line-height:1.75;letter-spacing:-0.01em;text-align:left;padding:32px 24px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.2em;text-indent:0}
#wemd h1{font-size:32px;font-weight:900;color:$colors.text_primary;margin-top:2em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:24px;font-weight:800;color:$colors.accent;margin-top:2em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.text_primary;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:700;color:#2563eb;margin-top:1.5em;margin-bottom:0.6em}
#wemd h4{font-size:16px;font-weight:600;color:$colors.text_secondary;margin-top:1.2em;margin-bottom:0.5em}
#wemd blockquote{border-left:6px solid $colors.quote_border;background:$colors.quote_background;padding:16px 24px;color:$colors.text_primary;font-style:normal;margin:1.2em 0}
#wemd code{background-color:$colors.text_primary;color:#fef08a;padding:2px 8px;border-radius:2px;font-size:0.88em;font-family:'JetBrains Mono', monospace}
#wemd pre{background:$colors.text_primary;border-radius:4px;padding:20px 24px;line-height:1.6;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.text_primary;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:square}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.text_primary;margin:2em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:0px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:left}
#wemd a{color:$colors.link_color;text-decoration:none}
#wemd strong{color:#dc2626;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 8px;border-radius:0px}
